  // --- Этология: терморегуляция/линька ---
  [eth.maintenance.thermoregulation]: {
    gate:    [NeedTag.COMFORT],                                  // без мема — «темп.комфорт» не учитываем
    present: [{ need: NeedTag.COMFORT, weight: 0.35 },           // базовый драйв к теплокомфорту
              { need: NeedTag.HEALTH,   weight: 0.10 }],
  },
  [eth.maintenance.ecdysis]: {
    gate:    [NeedTag.HYGIENE],                                  // «гигиена линьки»
    present: [{ need: NeedTag.HYGIENE, weight: 0.30 },
              { need: NeedTag.HEALTH,  weight: 0.10 }],
  },

  // --- Этология: социальность (универсальная) ---
  [eth.sociality.solitary]: {
    present: [{ need: NeedTag.PRIVACY, weight: 0.15 }],
  },
  [eth.sociality.cooperative]: {
    gate:    [NeedTag.BELONGING, NeedTag.COMMUNITY, NeedTag.LOYALTY],
    present: [{ need: NeedTag.BELONGING, weight: 0.30 },
              { need: NeedTag.COMMUNITY, weight: 0.25 },
