# 3) Агрегатор: из множества мемов → финальный профиль потребностей

```ts
export function computeNeedProfile(
  memesOwned: ReadonlyArray<MemeId>,
  ctx: NeedContext = {}
): Map<NeedTag, number> {
  const enabled = new Set<NeedTag>();
  const weights = new Map<NeedTag, number>();

  for (const m of memesOwned) {
    const imp = MemeToNeeds[m];
    if (!imp) continue;

    // gating
    imp.gate?.forEach(n => enabled.add(n));

    // additive presence
    imp.present?.forEach(({ need, weight }) => {
      enabled.add(need);
      weights.set(need, (weights.get(need) ?? 0) + weight);
    });

    // multiplicative modifiers
    imp.multiply?.forEach(({ need, factor }) => {
      weights.set(need, (weights.get(need) ?? 0) * factor);
    });
  }

  // === динамика: пример — терморегуляция
  if (memesOwned.includes(eth.maintenance.thermoregulation) && enabled.has(NeedTag.COMFORT)) {
    const ambient = ctx.ambientC ?? 20;
    const preferred = ctx.preferredC ?? 28; // для змей ок
    const delta = Math.abs(ambient - preferred);
    // 0..1 дискомфорт: 0 при совпадении, растет с дельтой (сгиньте/калибруем)
    const discomfort = Math.min(1, delta / 10);
    const add = 0.25 * discomfort; // усилить COMFORT пропорц. дискомфорту
    weights.set(NeedTag.COMFORT, (weights.get(NeedTag.COMFORT) ?? 0) + add);
  }

  // Кламп и фильтрация только по enabled
  for (const [need, w] of Array.from(weights.entries())) {
    if (!enabled.has(need)) { weights.delete(need); continue; }
    weights.set(need, Math.max(0, Math.min(1, w)));
  }

  return weights;
}
```

