# 1) Типы (юзабельно и расширяемо)

```ts
// 0 = полностью удовлетворено; 1 = критический дефицит
export type NeedLevel = number; // [0..1]

export interface NeedSpec {
  /** Включена ли потребность для данного существа (после мем-патчей) */
  enabled: boolean;

  /** Базовый "дрейф" к дефициту в час (если ничто не помогает). Пример: thirst 0.05..0.08 */
  baseAccumPerHour: number;

  /** Максимально возможное снижение дефицита в час от действий/среды (насыщаемость) */
  maxReliefPerHour: number;

  /** Доменно-зависимый приток дефицита (например, тепловой/холодовой стресс) */
  envK?: number;          // множитель внешнего стресса (например, |ΔT| для тепла/холода)
  envMaxPerHour?: number; // «потолок» внешнего вклада в час

  /** Пороговые зоны (эффекты ниже) */
  thresholds: {
    warn: number;     // ~ чуть заметно
    impaired: number; // ~ существенные штрафы
    severe: number;   // ~ опасно
    critical: number; // ~ коллапс/смертельный риск
  };

  /** Веса приоритезации действий: pressure = (baseWeight * level^alpha) * urgency */
  priority: {
    baseWeight: number; // 0..1
    alpha: number;      // 1..3 (кривизна)
    urgency: number;    // 0.5..2 (общий множитель)
  };

  /** Эффекты при достижении зон (мультипликаторы/тики урона/лок-ауты) */
  effects: {
    warn?:     Partial<EffectPack>;
    impaired?: Partial<EffectPack>;
    severe?:   Partial<EffectPack>;
    critical?: Partial<EffectPack>;
  };
}

/** Текущее состояние потребности */
export interface NeedState {
  level: NeedLevel;     // [0..1]
  lastUpdateTs: number; // ms
}

/** Что именно портится: мультипликаторы и/или периодические тики */
export interface EffectPack {
  moveMul?: number;          // 1=норма, <1 хуже
  actionSpeedMul?: number;
  accuracyMul?: number;
  aimStabilityMul?: number;
  staminaRegenMul?: number;
  decisionQualityMul?: number;
  panicChance?: number;      // 0..1
  healthDamagePerHour?: number; // hp/h
  forceBehavior?: 'seek_shelter' | 'sleep' | 'flee' | 'none';
}
```

# 2) Апдейтер (ядро динамики)

```ts
/** Δt в часах; reliefPerHour задаётся системой действий/средой, 0..spec.maxReliefPerHour */
export function tickNeed(
  state: NeedState,
  spec: NeedSpec,
  dtHours: number,
  context?: { envSignal?: number } // например: envSignal = |ambientC - preferredC|
): NeedState {
  if (!spec.enabled || dtHours <= 0) return state;

  const env = Math.min(
    spec.envMaxPerHour ?? Infinity,
    (spec.envK ?? 0) * Math.max(0, context?.envSignal ?? 0)
  );

  // Суммарный приток дефицита (дрейф + внешка)
  const up = (spec.baseAccumPerHour + env) * dtHours;

  // Суммарное "снятие" дефицита (питьё, еда, отдых, тень и т.п.) — система действий заполняет relief
  const relief = Math.min(spec.maxReliefPerHour * dtHours, pendingReliefForThisTick(spec)); // внедри свою очередь «снятий»

  const newLevel = clamp01(state.level + up - relief);
  return { level: newLevel, lastUpdateTs: nowMs() };
}

const clamp01 = (x: number) => Math.max(0, Math.min(1, x));
const nowMs = () => Date.now();
function pendingReliefForThisTick(_spec: NeedSpec): number { return 0; } // заглушка
```

- **baseAccumPerHour** — видо/индивидуальная скорость «порчи».
- **envK × envSignal** — как быстро «портится» от среды (например, |ΔT| для тепла/холода).
- **relief** — результат твоих действий/эффектов локаций (вода, пища, тень, сон и т.п.).

# 3) Эффекты (как применять)

```ts
export function effectsFor(level: NeedLevel, spec: NeedSpec): EffectPack {
  const e = spec.effects;
  if (level >= spec.thresholds.critical) return { ...e.severe, ...e.critical };
  if (level >= spec.thresholds.severe)   return { ...e.severe };
  if (level >= spec.thresholds.impaired) return { ...e.impaired };
  if (level >= spec.thresholds.warn)     return { ...e.warn };
  return {};
}
```

