```ts
// 0 = потребность удовлетворена; 1 = критический дефицит
export type NeedLevel = number; // [0..1]

export enum NeedZone { Normal='normal', Warn='warn', Impaired='impaired', Severe='severe', Critical='critical' }

export interface NeedThresholds {
  warn: number;      // ~начинает мешать
  impaired: number;  // ~существенно мешает
  severe: number;    // ~опасно
  critical: number;  // ~коллапс/риск смерти
}

// Эффекты — только функции/переключатели (никаких «мешков чисел»)
export interface NeedEffects {
  onEnterZone?(need: Need, zone: NeedZone, ctx: TickCtx): void;        // вход в зону
  onTick?(need: Need, dtHours: number, ctx: TickCtx): void;            // периодический тик (напр., hp-урон)
  // модификатор очков действия (приоритизация именно на действиях)
  modActionScore?(need: Need, action: Action, baseScore: number, ctx: ScoreCtx): number;
  // жёсткие запреты/переключатели поведения
  allowAction?(need: Need, action: Action, ctx: ScoreCtx): boolean;    // false = вето
  forcePolicy?(need: Need, ctx: ScoreCtx): ForcedPolicy | null;        // e.g., 'seek_shelter'
}

export type ForcedPolicy = 'seek_shelter' | 'sleep' | 'flee' | 'none';

// Спецификация потребности
export interface NeedSpec {
  tag: NeedTag;
  thresholds: NeedThresholds;

  // Базовая динамика:
  baseAccumPerHour: number;   // пассивный дрейф к дефициту (рост level), 0..?
  baseReliefPerHour: number;  // пассивное «саморазрешение» (падение level), 0..?

  // Внешние вклады/снятие — произвольные функции от контекста (никаких envK/envMaxPerHour):
  externalInflowPerHour?(ctx: TickCtx): number;   // +к дефициту (например, |ΔT| для холода/жары)
  externalReliefPerHour?(ctx: TickCtx): number;   // −из дефицита (например, тень/обогрев/покой)

  // Хуки эффектов
  effects?: NeedEffects;
}

// Текущее состояние «живёт» внутри инстанса Need (без отдельного NeedState)
export class Need {
  constructor(public spec: NeedSpec, public currentLevel: NeedLevel = 0) {}

  get zone(): NeedZone {
    const { warn, impaired, severe, critical } = this.spec.thresholds;
    const x = this.currentLevel;
    if (x >= critical) return NeedZone.Critical;
    if (x >= severe)   return NeedZone.Severe;
    if (x >= impaired) return NeedZone.Impaired;
    if (x >= warn)     return NeedZone.Warn;
    return NeedZone.Normal;
  }

  // основной апдейт уровня
  tick(dtHours: number, ctx: TickCtx) {
    const s = this.spec;
    const inflow  = s.baseAccumPerHour * dtHours + (s.externalInflowPerHour?.(ctx) ?? 0) * dtHours;
    const relief  = s.baseReliefPerHour * dtHours + (s.externalReliefPerHour?.(ctx) ?? 0) * dtHours
                  + ctx.reliefFromActions?.(this, dtHours, ctx) ?? 0;

    const prevZone = this.zone;
    this.currentLevel = clamp01(this.currentLevel + inflow - relief);

    if (s.effects?.onTick) s.effects.onTick(this, dtHours, ctx);
    const newZone = this.zone;
    if (newZone !== prevZone) s.effects?.onEnterZone?.(this, newZone, ctx);
  }
}

const clamp01 = (x:number)=> Math.max(0, Math.min(1, x));

// Контексты
export interface TickCtx {
  ambientC?: number;           // внешняя температура
  preferredC?: number;         // комфортная температура вида/индивида
  hydrationLevel?: number;     // 0..1
  awakeHours?: number;         // без сна
  reliefFromActions?: (need: Need, dtHours: number, ctx: TickCtx) => number;
  // + любые сенсоры/флаги окружения
}

export interface Action {
  tag: string;
  // адаптер: как твой action влияет на потребности (можно вычислять из rewardSecondary)
  expectedRelief?: Partial<Record<NeedTag, number>>; // «в час» или «мгновенно» — решай по системе
  riskTags?: string[]; // и др. поля экшена
}

export interface ScoreCtx extends TickCtx {
  // сюда можно прокинуть карту всех потребностей персонажа
  needs: Map<NeedTag, Need>;
  // коэффициенты риска, тактические веса и т.п.
}
```

# Гейтинг потребностей мемами

Никаких «enabled». Профиль потребностей **создаётся только из мемов** (и видовых пресетов):

```ts
// Какие мемы включают какие потребности
export const MemeGates: Record<MemeId, readonly NeedTag[]> = {
  [bio.vital_core]:           [NeedTag.FOOD, NeedTag.WATER, NeedTag.REST, NeedTag.HEALTH, NeedTag.COMFORT],
  [bio.reproduction.drive]:   [NeedTag.REPRODUCTION],
  [eth.maintenance.cleanliness_core]: [NeedTag.HYGIENE],
  // …и т.д.
};

// Патчи чисел от мемов (тонкая настройка видов/индивидуумов)
export interface NeedPatch {
  baseAccumPerHour?: number;
  baseReliefPerHour?: number;
  thresholds?: Partial<NeedThresholds>;
  // можно и функции подменять — см. ниже
  externalInflowPerHour?: NeedSpec['externalInflowPerHour'];
  externalReliefPerHour?: NeedSpec['externalReliefPerHour'];
  effects?: Partial<NeedEffects>;
}
export const MemePatches: Record<MemeId, Partial<Record<NeedTag, NeedPatch>>> = {
  [bio.thermoregulation.basic]: {
    [NeedTag.COMFORT]: {
      externalInflowPerHour: (ctx)=> {
        const d = Math.abs((ctx.ambientC ?? 20) - (ctx.preferredC ?? 28));
        // нормируем |ΔT| в 0..1 и умножаем на константу: полностью подконтрольно
        return Math.min(1, d/10) * 0.30;
      },
      externalReliefPerHour: (ctx)=> 0, // базовая модель: нет пассивной разрядки без действий/укрытия
    },
    [NeedTag.HEALTH]: { baseReliefPerHour: 0.02 }, // немного быстрее самовосст при нормальной терме
  },
  [eth.maintenance.thermoregulation]: {
    [NeedTag.COMFORT]: {
      externalReliefPerHour: (ctx)=> 0.25, // умеет находить тень/греться => пассивная разрядка быстрее
    },
  },
  // …и т.д.
};

// Конструктор профиля из мемов
export function buildNeedsFromMemes(memesOwned: readonly MemeId[], baseSpecs: Record<NeedTag, NeedSpec>): Map<NeedTag, Need> {
  const gated = new Set<NeedTag>();
  for (const m of memesOwned) (MemeGates[m] ?? []).forEach(n => gated.add(n));

  const needs = new Map<NeedTag, Need>();
  for (const n of gated) {
    const base = deepClone(baseSpecs[n]);
    // применяем патчи
    for (const m of memesOwned) {
      const p = MemePatches[m]?.[n];
      if (!p) continue;
      Object.assign(base, p); // простое слияние (функции тоже можно заменить)
      if (p.effects) base.effects = { ...(base.effects ?? {}), ...p.effects };
    }
    needs.set(n, new Need(base, 0));
  }
  return needs;
}
```

# Приоритизация именно действий (с “охранником безопасности”)

```ts
// Базовый скор нужды — кривой по уровню (без постоянных «приоритетов потребности»)
function needPressure(n: Need, alpha=1.4): number {
  return Math.pow(n.currentLevel, alpha); // 0..1
}

// Оценка действия
export function scoreAction(a: Action, ctx: ScoreCtx): number {
  // 1) safety-guard: жёсткий вето от потребностей (например, COMFORT в critical запрещает «выйти на мороз»)
  for (const need of ctx.needs.values()) {
    if (need.spec.effects?.allowAction && !need.spec.effects.allowAction(need, a, ctx)) {
      return -Infinity;
    }
  }

  // 2) базовый скор (тактический, экономический и т.д.) — подставь свою логику
  let score = 0;

  // 3) умножаем/прибавляем вкладом нужд через хуки
  for (const need of ctx.needs.values()) {
    const p = needPressure(need);
    if (need.spec.effects?.modActionScore) {
      score = need.spec.effects.modActionScore(need, a, score, ctx);
    }
    // простейшая привязка к заявленному relief: чем сильнее действие снимает острую нужду — тем выше
    const rel = a.expectedRelief?.[need.spec.tag] ?? 0;
    score += p * rel * 100; // масштаб выбери под свою шкалу
  }

  return score;
}
```

