// Вода: растёт быстро, снимается быстро
const WATER: NeedSpec = {
  tag: NeedTag.WATER,
  thresholds: { warn:0.2, impaired:0.4, severe:0.6, critical:0.8 },
  baseAccumPerHour: 0.06,
  baseReliefPerHour: 0.00,
  externalInflowPerHour: undefined,       // захочешь — учти жару в патче мемами
  externalReliefPerHour: undefined,
  effects: {
