      if (need.zone === NeedZone.Severe) { ctx.applyHpDamage?.(0.5*dt); }
      if (need.zone === NeedZone.Critical) { ctx.applyHpDamage?.(1.5*dt); }
    },
    allowAction(need, action, ctx) {
      // пример: на Critical WATER блокируем любые «дальние походы без воды»
      if (need.zone === NeedZone.Critical && action.tag === 'GO_LONG_TRAVEL') return false;
      return true;
    },
    modActionScore(need, action, base, ctx) {
      // действие «пить» резко подскакивает при высокой жажде
      if (action.tag === 'DRINK_WATER') {
        return base + Math.pow(need.currentLevel, 1.3) * 150;
      }
      return base;
    },
  },
};

// Комфорт (терма): только внешкой крутится
