  tag: NeedTag.COMFORT,
  thresholds: { warn:0.15, impaired:0.35, severe:0.55, critical:0.75 },
  baseAccumPerHour: 0,
  baseReliefPerHour: 0,
  externalInflowPerHour: (ctx)=> {
