# Типы (лаконично)

```ts
// Зоны — как и раньше (если держишь Normal, он просто не участвует в гейтах)
export enum NeedZone { Warn='Warn', Impaired='Impaired', Severe='Severe', Critical='Critical' }

// Трешхолды действия по конкретной Потребности:
//  - type: 'positive'  => действие РАЗРЕШАЕТСЯ, когда дефицит достиг нужной зоны/доли зоны
//  - type: 'negative'  => действие ЗАПРЕЩАЕТСЯ, когда дефицит достиг нужной зоны/доли зоны
export interface ActionNeedThreshold {
  type: 'positive' | 'negative';
  tresholdLevels: Partial<Record<NeedZone, number>>; // доля внутри зоны [0..1]
}

// В самом действии — просто мапа по нуждам.
// Ключ — NeedTag, значение — описанный выше словарь.
export interface ActionDefinition {
  tag: string;
  // ...твои существующие поля: requiredMemes, tradeEffect, rewardSecondary и пр.
  needThresholds?: Partial<Record<NeedTag, ActionNeedThreshold>>;
}
```

# Утилита допуска (одна функция)

```ts
// Умеем вычислять текущую зону и «долю внутри зоны» по level ∈ [0..1] и порогам нужды
function zoneAndFrac(level: number, thr: {warn:number; impaired:number; severe:number; critical:number}): {zone: NeedZone; frac: number} {
  const clamp01 = (x:number)=> Math.max(0, Math.min(1, x));
  if (level >= thr.critical) {
    const denom = Math.max(1e-6, 1 - thr.critical);
    return { zone: NeedZone.Critical, frac: clamp01((level - thr.critical) / denom) };
  }
  if (level >= thr.severe) {
    const denom = Math.max(1e-6, thr.critical - thr.severe);
    return { zone: NeedZone.Severe, frac: clamp01((level - thr.severe) / denom) };
  }
  if (level >= thr.impaired) {
    const denom = Math.max(1e-6, thr.severe - thr.impaired);
    return { zone: NeedZone.Impaired, frac: clamp01((level - thr.impaired) / denom) };
  }
  if (level >= thr.warn) {
    const denom = Math.max(1e-6, thr.impaired - thr.warn);
    return { zone: NeedZone.Warn, frac: clamp01((level - thr.warn) / denom) };
  }
  // ниже warn — вне зон (для этой схемы просто frac=0 в Warn)
  const denom = Math.max(1e-6, thr.impaired - thr.warn);
  return { zone: NeedZone.Warn, frac: 0 };
}

// Главная проверка допуска по нуждам.
export function actionAllowedByNeedsSimple(
  action: ActionDefinition,
  needs: Map<NeedTag, { level: number; thresholds: {warn:number; impaired:number; severe:number; critical:number} }>
): boolean {
  const gates = action.needThresholds;
  if (!gates) return true;

  for (const [needTag, gate] of Object.entries(gates) as [NeedTag, ActionNeedThreshold][]) {
    const needState = needs.get(needTag);
    if (!needState) return false; // у существа вообще нет такой потребности → действие недоступно

    const { zone, frac } = zoneAndFrac(needState.level, needState.thresholds);
    const req = gate.tresholdLevels[zone];

    // Если для текущей зоны ключ не задан:
    //  - для 'positive' трактуем как "не пройдено" (нет явного разрешения);
    //  - для 'negative' трактуем как "нет запрета".
    if (req === undefined) {
      if (gate.type === 'positive') return false;
      else continue;
    }

    if (gate.type === 'positive') {
      if (frac < req) return false;       // надо «дорасти» внутри зоны
    } else { // 'negative'
      if (frac >= req) return false;      // достиг нужной доли → действие запрещено
    }
  }
  return true;
}
```

> Примечание: `tresholdLevels` — **доля внутри зоны** (0..1).  
> Примеры:  
> • `{ Warn: 0 }` — разрешить сразу при входе в Warn.  
> • `{ Severe: 0.5 }` — разрешить/запретить только с середины Severe.  
> • Пустой ключ для зоны в `positive` = нет разрешения для этой зоны (жёстко).  
> • Пустой ключ для зоны в `negative` = нет запрета для этой зоны.

