отлично, фиксируем лаконичную схему с `atLeast / atMost` и словарём по нуждам прямо в экшене. Ниже — готовые типы и утилита проверки допуска, плюс примеры (еда/вода/поход/сон).

# Типы

```ts
// Зоны дефицита (только дискретные пороги)
export enum NeedThresholdEnum {
  WARN = 'WARN',
  IMPAIRED = 'IMPAIRED',
  SEVERE = 'SEVERE',
  CRITICAL = 'CRITICAL',
}

// Если хочешь сохранить старое имя с опечаткой:
export const NeedTresholdEnum = NeedThresholdEnum;
export type NeedTresholdEnum = NeedThresholdEnum;

// Пороговая «решётка» для конкретной потребности
export interface NeedThresholds {
  warn: number;
  impaired: number;
  severe: number;
  critical: number;
}

// Гейт экшена по конкретной потребности
export interface NeedGate {
  atLeast?: NeedThresholdEnum; // экшен разрешён, если текущая зона >= atLeast
  atMost?: NeedThresholdEnum;  // и/или запрещён, если текущая зона > atMost
}

// В самом действии — просто словарь: какая потребность → какой гейт
export interface ActionDefinition {
  tag: string;
  // ...твои существующие поля (requiredMemes, rewardSecondary, tradeEffect, etc.)
  needThresholds?: Partial<Record<NeedTag, NeedGate>>;
}
```

# Утилита допуска

```ts
// определить дискретную зону по level∈[0..1] и порогам
export function zoneOf(level: number, t: NeedThresholds): NeedThresholdEnum | null {
  if (level >= t.critical) return NeedThresholdEnum.CRITICAL;
  if (level >= t.severe)   return NeedThresholdEnum.SEVERE;
  if (level >= t.impaired) return NeedThresholdEnum.IMPAIRED;
  if (level >= t.warn)     return NeedThresholdEnum.WARN;
  return null; // ниже warn — «нормально»
}

const order = [
  NeedThresholdEnum.WARN,
  NeedThresholdEnum.IMPAIRED,
  NeedThresholdEnum.SEVERE,
  NeedThresholdEnum.CRITICAL,
] as const;
const idx = (z: NeedThresholdEnum) => order.indexOf(z);

// главная проверка: все требуемые гейты должны пройти
export function actionAllowedByNeeds(
  action: ActionDefinition,
  needs: Map<NeedTag, { level: number; thresholds: NeedThresholds }>,
): boolean {
  const gates = action.needThresholds;
  if (!gates) return true;

  for (const [needTag, gate] of Object.entries(gates) as [NeedTag, NeedGate][]) {
    const state = needs.get(needTag);
    if (!state) return false; // существо не «знает» эту потребность → экшен недоступен

    const z = zoneOf(state.level, state.thresholds);
    // ниже WARN — считаем как «зона отсутствует»
    const hasZone = z !== null;

    if (gate.atLeast) {
      if (!hasZone) return false;
      if (idx(z!) < idx(gate.atLeast)) return false;
    }
    if (gate.atMost) {
      // если ниже WARN, то любая atMost пройдёт
      if (hasZone && idx(z!) > idx(gate.atMost)) return false;
    }
  }
  return true;
}
```

