# Δ `memes/deps.ts` — лестница IQ и «минимальные IQ» для мемов

```ts
import { memes, iq } from './index';
import type { MemeId } from './types'; // или откуда у тебя берётся тип MemeId

// 1) Лестница IQ (каждый следующий уровень требует предыдущий)
export const memeDeps: Record<MemeId, readonly MemeId[]> = {
  // … твои текущие зависимости …

  [iq.level_3]:  [iq.level_2],
  [iq.level_4]:  [iq.level_3],
  [iq.level_5]:  [iq.level_4],
  [iq.level_6]:  [iq.level_5],
  [iq.level_7]:  [iq.level_6],
  [iq.level_8]:  [iq.level_7],
  [iq.level_9]:  [iq.level_8],
  [iq.level_10]: [iq.level_9],
};

// helper: аккуратно дописать IQ-требование к существующему узлу,
// не ломая уже заданные зависимости и не создавая дубликатов
function addMinIQ(target: MemeId, minLevel: MemeId) {
  const base = memeDeps[target] ?? [];
  if (!base.includes(minLevel)) {
    memeDeps[target] = [...base, minLevel] as const;
  }
}

// 2) Минимальные IQ для ключевых мемов (подобраны «консервативно»)
// ── базовые сенсомоторные и этологические вещи ────────────────────────────────
addMinIQ(memes.core.perception,         iq.level_2);
addMinIQ(memes.core.motor_coordination, iq.level_2);

addMinIQ(memes.soc.shared_attention,    iq.level_4);
