addMinIQ(memes.comm.signage,            iq.level_8);

// ── когниция/счёт/время/пространство/стандарты ───────────────────────────────
addMinIQ(memes.cog.counting.tally,           iq.level_6);
addMinIQ(memes.cog.number_concept,           iq.level_7);
addMinIQ(memes.cog.measurement.rudimentary,  iq.level_7);
