// ── организация ───────────────────────────────────────────────────────────────
addMinIQ(memes.org.scheduling,          iq.level_7);
addMinIQ(memes.org.workshop_practice,   iq.level_7);
addMinIQ(memes.org.duty_roster,         iq.level_8); // обычно требует запись/публикацию

// ── орудия/огонь/тепло ────────────────────────────────────────────────────────
addMinIQ(memes.tech.tool.use_basic,     iq.level_5);
addMinIQ(memes.tech.tool.shaping,       iq.level_6);
addMinIQ(memes.tech.tool.making,        iq.level_7);

addMinIQ(memes.tech.fire.use,           iq.level_6); // «поддерживать найденный»
addMinIQ(memes.tech.fire.control,       iq.level_8); // «разжигать/гасить/управлять»

addMinIQ(memes.tech.heat.core,          iq.level_7);
addMinIQ(memes.tech.heat.space.core,    iq.level_7);
addMinIQ(memes.tech.heat.space.hearth,  iq.level_7);
addMinIQ(memes.tech.heat.industrial,    iq.level_9);

// ── пищевые технологии ────────────────────────────────────────────────────────
addMinIQ(memes.tech.food.prep.butchering_basic, iq.level_6);
addMinIQ(memes.tech.food.prep.milling_basic,    iq.level_7);
addMinIQ(memes.tech.food.prep.leavening_basic,  iq.level_8);

addMinIQ(memes.tech.food.preservation.fermentation, iq.level_7);
addMinIQ(memes.tech.food.preservation.drying,       iq.level_7);
