// ── этологические/охота/бой (оставляем «животным») ───────────────────────────
// если у тебя есть эти узлы — вешаем их на самые низкие IQ (рептилия/млекоп.)
try { addMinIQ((memes as any).eth.maintenance.cleanliness_core, iq.level_2); } catch {}
try { addMinIQ((memes as any).eth.maintenance.ecdysis,          iq.level_2); } catch {}
try { addMinIQ((memes as any).eth.sociality.solitary,           iq.level_2); } catch {}
try { addMinIQ((memes as any).eth.sociality.cooperative,        iq.level_4); } catch {}
