// стало:
[memes.comm.signaling]: [
    /* ...старые зависимости... */,
    memes.cog.iq3,
];

// было:
[memes.soc.shared_attention]: [ /* ... */ ],
// стало:
[memes.soc.shared_attention]: [
    /* ...старые зависимости... */,
    memes.cog.iq4,
];

// было:
[memes.comm.language.spoken]: [ /* ... */ ],
// стало:
[memes.comm.language.spoken]: [
    /* ...старые зависимости... */,
    memes.cog.iq6,
];

// было:
[memes.comm.language.written]: [ /* ... */ ],
// стало:
[memes.comm.language.written]: [
    /* ...старые зависимости... */,
